<?php require_once __DIR__.'/includes/functions.php';require_role(['admin','staff']);$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$status=$_GET['status']??'';$sql="SELECT t.id,t.type,t.status,t.requested_at,t.due_date,t.released_at,t.returned_at,u.name requester,u.email,b.title book_title FROM transactions t JOIN users u ON u.id=t.user_id JOIN books b ON b.id=t.book_id WHERE DATE(t.requested_at) BETWEEN ? AND ?";$types='ss';$vals=[$from,$to];if($status==='overdue'){$sql.=" AND t.status='released' AND t.due_date<CURDATE()";}elseif(in_array($status,['pending','approved','rejected','released','returned','cancelled','expired'],true)){$sql.=' AND t.status=?';$types.='s';$vals[]=$status;}$sql.=' ORDER BY t.requested_at DESC';$s=$db->prepare($sql);$s->bind_param($types,...$vals);$s->execute();$rows=$s->get_result();$summary=$db->query("SELECT status,COUNT(*) n FROM transactions GROUP BY status");$title='Reports';require 'includes/header.php';?><h1>Reports & summaries</h1><div class="grid"><?php while($sum=$summary->fetch_assoc()):?><div class="card"><div class="muted"><?=e(ucfirst($sum['status']))?></div><div class="stat"><?=$sum['n']?></div></div><?php endwhile;?></div><div class="panel no-print"><form class="filters" method="get"><div><label>From</label><input type="date" name="from" value="<?=e($from)?>" required></div><div><label>To</label><input type="date" name="to" value="<?=e($to)?>" required></div><div><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach(['pending','approved','rejected','released','returned','cancelled','expired','overdue'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><button>Generate report</button> <button type="button" class="btn secondary" onclick="window.print()">Print / Save PDF</button></form></div><div class="panel"><h2>Transaction report (<?=e($from)?> to <?=e($to)?>)</h2><p>Total matching records: <b><?=$rows->num_rows?></b></p><div class="table-wrap"><table><tr><th>ID</th><th>Requester</th><th>Book</th><th>Type</th><th>Status</th><th>Requested</th><th>Due / Returned</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['requester'])?><br><?=e($r['email'])?></td><td><?=e($r['book_title'])?></td><td><?=e($r['type'])?></td><td><?=e($r['status'])?></td><td><?=e($r['requested_at'])?></td><td><?=e($r['due_date']??'—')?> / <?=e($r['returned_at']??'—')?></td></tr><?php endwhile;?></table></div></div><?php require 'includes/footer.php';?>
